    CODE[1] = 0x08000000u | (((BASE + 16 + 4 * entry) >> 2) & 0x03FFFFFFu);   /* j to the first copy's entry */
    CODE[2] = NOP;
    for (uint32_t i = 0; i < n; i++) CODE[4 + pw[i][0]] = pw[i][1];
